def flatten_keys(d: dict) -> dict:
    result = {}

    def _flatten(val, prefix: str) -> None:
        if isinstance(val, dict):
            if not val and prefix:
                result[prefix] = {}
            else:
                for k, v in val.items():
                    new_key = f"{prefix}.{k}" if prefix else str(k)
                    _flatten(v, new_key)
        elif isinstance(val, list):
            if not val:
                result[prefix] = []
            else:
                for i, item in enumerate(val):
                    new_key = f"{prefix}[{i}]"
                    _flatten(item, new_key)
        else:
            result[prefix] = val

    _flatten(d, "")
    return result
